quests[5407] = { id = 5407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invader's Scourgestones", progress = "An Invader's Scourgestone is the insignia of the Scourge's elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.\n\nThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.", completion = "Congratulations, {name} - I am pleased to award you with an Argent Dawn valor token!\n\nEach valor token handed out to worthy recipients is a sign of the tide turning against the Scourge.  With more and more heroes fighting the Scourge in their own lands, the Argent Dawn will assuredly be at the forefront when the time comes to wage war on the ultimate evil of the Scourge.  I hope that the valor you've shown what it took to acquiring your token will carry the day then as well!" }
quests[5408] = { id = 5408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minion's Scourgestones", progress = "A Minion's Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term \"weaker\" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.\n\nThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I'm happy to do, provided you have earned enough scourgestones!", completion = "Congratulations, {name} - I am pleased to award you with an Argent Dawn valor token!\n\nThe tokens serve two purposes.  One - they can be used to further your standing within the Argent Dawn; to do so may avail you options and rewards that are reserved for our honored and revered allies.  Two - they can be given to our quartermasters, along with coin, as payment for some of the Dawn's more prized items.\n\nWhatever you decide, know that you are earning your commission.  Well done!" }
quests[5421] = { id = 5421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish in a Bucket", description = "I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon!\n\nBelow the docks here in Shadowprey Village, I've many shellfish traps.  If you're kind enough to do my work and collect me my shellfish, then I'll reward you with something you want... get my drift mon?", progress = "Ya got mah shellfish, mon?", completion = "Sweet mon, nothing beats work being done, especially if it's someone else doing the work... eh?", objectives = "Jinar'Zillen wants you to collect 5 Shellfish from the traps near Shadowprey Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5441] = { id = 5441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Peons", description = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right {race} for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLousy slacking peons...", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!", objectives = "Use the Foreman's Blackjack on Lazy Peons when they're sleeping. Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5461] = { id = 5461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Human, Ras Frostwhisper", description = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.\n\nUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.\n\nYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, {name}.", progress = "A keepsake of remembrance is a rare find, {name}.", completion = "I had doubted the possibility of such an item existing. This certainly opens up an incredible opportunity - one we must not squander.\n\nPrepare yourself, {name}, for what I am about to ask of you will take you into the depths of hell.", objectives = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5462] = { id = 5462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dying, Ras Frostwhisper", description = "Upon tainted soil, the keepsake must be attuned.\n\nIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.\n\nIt is those grounds that must be found.\n\nThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, {name}.", progress = "Do not ask questions of which you do not want answers.", completion = "<Leonid looks over the keepsake.>\n\nYour quandary stirs up memories that I had hoped would never resurface.", objectives = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5463] = { id = 5463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethil's Gift", description = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.\n\n<Leonid gazes at the ground and then looks up at you.>\n\nYes, {race}, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge.", progress = "The area around Menethil's Gift is exceptionally cold.", completion = "You place the keepsake on the tainted soil.", objectives = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5464] = { id = 5464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethil's Gift", description = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack.", progress = "<Leonid shudders.>", completion = "As the soul clung to the keepsake, so shall it cling to the physical form of Ras Frostwhisper.", objectives = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5465] = { id = 5465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulbound Keepsake", description = "Return to Marduke with the keepsake, {name}. He will instruct you in its use.", progress = "Have you done the impossible?", completion = "I was certain that you would be joining me as another hapless spirit.", objectives = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5466] = { id = 5466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich, Ras Frostwhisper", description = "There is but one task remaining, {name}. Confront the lich, Ras Frostwhisper, in his lair.\n\nUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!\n\nWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.", progress = "You carry the burden of ten thousand restless souls, {name}.", completion = "Ten thousand souls cry out in unison, {name}! You have struck a mortal blow to the Scourge and their masters.", objectives = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5481] = { id = 5481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill graveyard.", progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nVery well, you're here now and that's all that matters. Since I'm not going to bother to try to explain things to that abomination how about you collect what I really need... doom weed!", objectives = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5482] = { id = 5482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doom Weed", description = "So you can see the predicament that I'm in, {name}. That thing is out there collecting the wrong weeds! I'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", progress = "This had better be good. I trust you have all of the doom weed that I require?", completion = "Ah, my doom weed. Excellent!\n\n<Junior Apothecary Holland rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, {name}. As promised, here is the reward that you deserve.", objectives = "Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5501] = { id = 5501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Collector", description = "We're sitting on a goldmine here, I tell you - a goldmine!  Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them.\n\nThere's a caravan that comes by and picks up my Kodo bones and then sells them at Shadowprey Village.  If you can travel to the kodo graveyard south of here and bring me ten Kodo bones, I'll give you something in return.  Is it a deal?", progress = "Do you have the bones?  The caravan will be here any moment.  I need just ten more kodo bones to reach a career high.  A career high, I tell you!", completion = "Ah, goodie!  My bones!\n\nI can't wait till the chaps at home see my face on the front cover of Goblin'preneur.  I'll be the richest goblin in the world... and my physical education teacher said I would never amount to anything.", objectives = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5502] = { id = 5502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warden of the Horde", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he's still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", progress = "It is a pleasure to see you again, {name}.  Have you attended to the duties you've volunteered for during Children's Week?", completion = "May the spirits bless you, {name}.  You've done more for Grunth than most would ever think of doing for him.  Thank you - you're the epitome of what it means to be a hero of the Horde.\n\nThe orphans will love your gift; it's not often that they get a new toy.\n\nGrunth had so much fun with you, {name}.  He wanted to give you one of his favorite pets to remember him by.", objectives = "Purchase a Foam Sword Rack from Blax Bottlerocket in Orgrimmar's Drag. Then return your ward to the Orgrimmar orphanage by speaking with Orphan Matron Battlewail in The Drag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5503] = { id = 5503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Dawn Commission", sourceObjective = "All who fight evil on behalf of the Argent Dawn must don our commission.  Wearing such will earn your right to claim rewards our quartermasters have to offer.\n\nWhile under commission, you'll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess.  Procure these insignia and bring them to me.  For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.\n\nAchieve your destiny, {class} - join the fight today!", sourceObjectiveStatus = "unverified-source-field" }
quests[5504] = { id = 5504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, {name}.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5505] = { id = 5505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Scholomance", progress = "Well, here you are, {name} - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", completion = "Good luck, mighty hero. May your victories continue to bring you fame and power as you lay waste to Scholomance!" }
quests[5507] = { id = 5507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, {name}.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", progress = "Ah, noble {class}!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, {name}.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5508] = { id = 5508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruptor's Scourgestones", progress = "A Corruptor's Scourgestone is the insignia of the Scourge's overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!\n\nOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one of these insignia.  Use caution in acquiring one, {name} - such powerful beings are not to be trifled with.", completion = "Congratulations, {name} - I am pleased to award you with an Argent Dawn valor token!\n\nTo acquire a valor token in such a manner indicates that you are a true hero in the cause of good.  We value all effort brought to bear against the Scourge, but to take down one of their leaders is to truly deliver onto them a crushing defeat!\n\nFor the Dawn, my brother!" }
quests[5509] = { id = 5509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invader's Scourgestones", progress = "An Invader's Scourgestone is the insignia of the Scourge's elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.\n\nThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.", completion = "Congratulations, {name} - I am pleased to award you with an Argent Dawn valor token!\n\nEach valor token handed out to worthy recipients is a sign of the tide turning against the Scourge.  With more and more heroes fighting the Scourge in their own lands, the Argent Dawn will assuredly be at the forefront when the time comes to wage war on the ultimate evil of the Scourge.  I hope that the valor you've shown what it took to acquiring your token will carry the day then as well!" }
quests[5510] = { id = 5510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minion's Scourgestones", progress = "A Minion's Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term \"weaker\" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.\n\nThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I'm happy to do, provided you have earned enough scourgestones!", completion = "Congratulations, {name} - I am pleased to award you with an Argent Dawn valor token!\n\nThe tokens serve two purposes.  One - they can be used to further your standing within the Argent Dawn; to do so may avail you options and rewards that are reserved for our honored and revered allies.  Two - they can be given to our quartermasters, along with coin, as payment for some of the Dawn's more prized items.\n\nWhatever you decide, know that you are earning your commission.  Well done!" }
quests[5511] = { id = 5511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Scholomance", progress = "Well, here you are, {name} - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", completion = "Good luck, mighty hero. May your victories continue to bring you fame and power as you lay waste to Scholomance!" }
quests[5513] = { id = 5513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, {name}.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", progress = "Ah, noble {class}!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, {name}.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5514] = { id = 5514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", progress = "Yeah, I know who you are, and I know why you're here.  Dithers sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Dithers said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Dithers imbue them already?  Excellent... otherwise, it would have been a long trip back to the Bulwark for you.", objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5515] = { id = 5515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinov's Bag of Horrors", description = "A great weight has been lifted from our hearts, {name}, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.\n\nBefore you may face Kirtonos, however, you must first secure a method in which to summon him.\n\nIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.\n\nFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.", progress = "<Eva fades in and out of focus.>", completion = "The bag of horrors!", objectives = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[5517] = { id = 5517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> {name} - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
